MultiLanguageSpellData['mx'][295076] = {name = "Erupción enloquecedora", additional_info = "Alcance de 300 m\nInstante\n[q]Za'qul crea una fisura que infligirá 17413 p. de daño de las sombras a todos los enemigos cuando haga erupción. Si Za'qul se mueve a la fisura antes de la erupción, solo los enemigos en un radio de 10 m alrededor de la erupción sufrirán 17378 p. de daño de las sombras.\n\n Cuando Za'qul está en la erupción, recibe una acumulación de Oscuridad perforada ."}
MultiLanguageSpellData['mx'][295078] = {name = "Sangre de vida", additional_info = "[q0][Azerite Essence][q]Cada 18-25 s, un fragmento de sangrevida emerge del terreno cercano durante 12 s.\n\nFragmento de sangrevida\n Les otorga a ti y a cualquier otro aliado que use Resonancia de veta del mundo 13 p. para su estadística principal mientras estén en un radio de 12 m del fragmento de sangrevida. Puedes obtener el beneficio de un máximo de 4 fragmentos de sangrevida a la vez."}
