MultiLanguageSpellData['mx'][299333] = {name = "Sangre de vida", additional_info = "[q0][Azerite Essence][q]Cada 1-25 s, un fragmento de sangrevida emerge del terreno cercano durante 18 s.\n\nFragmento de sangrevida\n Les otorga a ti y a cualquier otro aliado que use Resonancia de veta del mundo 13 p. para su estadística principal mientras estén en un radio de 12 m del fragmento de sangrevida. Puedes obtener el beneficio de un máximo de 4 fragmentos de sangrevida a la vez."}
MultiLanguageSpellData['mx'][299334] = {name = "Resonancia de veta del mundo", additional_info = "[q0][Azerite Essence]{Instante} {1 min de reutilización}\n[q]Concentra energía en el Corazón de Azeroth, lo que hace que inmediatamente emerjan 3 fragmentos de sangrevida en el terreno cercano durante 18 s, y que aumente la estadística principal que se obtiene a partir de Fragmentos de sangrevida un 300% durante 18 s.\n\nFragmento de sangrevida\n Les otorga a ti y a otro aliado que use Resonancia de veta del mundo 13 p. de estadística principal mientras estén a un radio de 12 m del fragmento. Puedes obtener el beneficio de un máximo de 4 fragmentos de sangrevida a la vez."}
MultiLanguageSpellData['mx'][299335] = {name = "Energía enfocada", additional_info = "[q0][Azerite Essence][q]Tus hechizos y habilidades que infligen daño te otorgan [ 5 * (1.5)] p. de celeridad durante 4 s. Este efecto se acumula hasta 10 veces. Esta celeridad se pierde si dejas de usar hechizos o habilidades contra el objetivo inicial."}
MultiLanguageSpellData['mx'][299336] = {name = "Rayo de azerita concentrado", additional_info = "[q0][Azerite Essence]Hechizo de 1.333 seg 1.5 min de reutilización\n[q]Concentra el exceso de energía de azerita en el Corazón de Azeroth y luego la expulsa para infligir ( 891 * 10) p. de daño de fuego a todos los enemigos que están frente a ti durante 3 s."}
MultiLanguageSpellData['mx'][299337] = {name = "Energía enfocada", additional_info = "[q0][Azerite Essence][q]Tus hechizos y habilidades que infligen daño te otorgan [ 5 * (1.5)] p. de celeridad durante 4 s. Este efecto se acumula hasta 10 veces. La celeridad se pierde si dejas de usar hechizos o habilidades contra el objetivo inicial.\n\n Si no tienes acumulaciones de Energía concentrada, generas 3 acumulaciones de tu primera habilidad o hechizo que inflija daño."}
MultiLanguageSpellData['mx'][299338] = {name = "Rayo de azerita concentrado", additional_info = "[q0][Azerite Essence]Hechizo de 1.333 seg 1.5 min de reutilización\n[q]Concentra el exceso de energía de azerita en el Corazón de Azeroth y luego la expulsa para infligir ( 891 * 10) p. de daño de fuego a todos los enemigos que están frente a ti durante 3 s. Puede lanzarse en movimiento."}
