MultiLanguageSpellData['mx'][299343] = {name = "Protocolo de purificación", additional_info = "[q0][Azerite Essence]Aproximadamente 2 activaciones por minuto\n[q]MADRE ha agregado un Protocolo de purificación a tu Corazón de Azeroth para que tus hechizos y habilidades dañinos lancen una ráfaga de energía de azerita contra tu objetivo, inflijan [ 563 * (1 + Versatilidad)] p. de daño de fuego a cualquier enemigo en un radio de 8 m, y te sanen por [ 255 * (1 + Versatilidad)] cada 2 s durante 8 s.\n\n Protocolo de purificación inflige un 50% más de daño contra aberraciones."}
MultiLanguageSpellData['mx'][299344] = {name = "Burbuja de seguridad", additional_info = "{Instante} {10 seg de reutilización}\n[q]Otorga invulnerabilidad durante 3 s, elimina todos los efectos de veneno, enfermedad y mágicos, y restablece un 35% de salud máxima."}
