MultiLanguageSpellData['mx'][303007] = {name = "Leal hasta el final", additional_info = "[q0]Poder Azerita\n[q]Tu maestría aumenta 31 p. y 11 p. más por cada aliado que también esté afectado por Leal hasta el final, hasta un máximo de 92 p.\n\n Cuando mueres, tus aliados obtienen p. de golpe crítico, celeridad y versatilidad equivalentes a la bonificación de maestría que les otorgó este atributo."}
MultiLanguageSpellData['mx'][303008] = {name = "Mareas ondulantes", additional_info = "[q0]Poder Azerita\n[q]Tus hechizos y habilidades que infligen daño tienen la probabilidad de hacer caer una ola enorme que inflige 548 p. de daño de escarcha sobre tu objetivo.\n\n Cuando tu salud cae por debajo de un 50%, obtienes un escudo que absorbe 4297 p. de daño dentro de 8 s. Cuando esto ocurre, Mareas ondulantes no puede volver a activarse durante 45 s."}
