MultiLanguageSpellData['mx'][307041] = {name = "Explosión de vendaval", additional_info = "Rango ilimitado\nInstante\n[q]Libera una explosión de vendaval que inflige 28196 p. de daño de fuego, repele a los jugadores en un radio de 30 m e inflige 14062 p. de daño de fuego a todos los jugadores que estén a más de 30 m de distancia.\n\n Después, lanza bolas de fuego hacia ubicaciones enemigas aleatorias que infligen 23450 p. de daño de fuego a los enemigos en un radio de 5 m del impacto."}
MultiLanguageSpellData['mx'][307042] = {name = "Antígeno adaptable", additional_info = "Instante\n[q]El Antígeno de pesadilla obtiene Antígeno adaptable periódicamente, lo que aumenta el daño infligido un 10% e impide que la ralentización llegue a menos de un 10% de la velocidad normal.\n Este efecto se acumula.\n(3s de reutilización)"}
