MultiLanguageSpellData['mx'][310484] = {name = "Granada cascanueces", additional_info = "Hechizo de 2 seg\nComponentes:\nPuñado de tornillos de lestrita (3), Abrasivo de pulido poroso (2), Mena de lestrita\nProfesión:\nIngeniería de Shadowlands (10)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n30\n\n(2)\n[q2]Uso: Inflige 13939 p. de daño de naturaleza a todos los enemigos en un radio de 5 m. (5 Min Reutilización)\nNecesitas ser de nivel 51"}
MultiLanguageSpellData['mx'][310485] = {name = "Mina terrestre de las sombras", additional_info = "Hechizo de 2 seg\nComponentes:\nPuñado de tornillos de lestrita (5), Abrasivo de pulido poroso (3), Mena de lestrita (3)\nProfesión:\nIngeniería de Shadowlands (20)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n75\n\n(2)\n[q2]Uso: Coloca una mina en el suelo que explota cuando un enemigo la pisa, inflige 13939 p. de daño de las sombras a todos los enemigos que están en un radio de 5 m y los repele. (5 Min Reutilización)\nRequiereIngeniería de Shadowlands\n(1)"}
MultiLanguageSpellData['mx'][310486] = {name = "Lanzador de bómbola", additional_info = "Hechizo de 2 seg\nComponentes:\nGranada cascanueces (3), Engranajes digeridos por gusanos , Abrasivo de pulido poroso (5), Corteza crepuscular , Hilo de penumbra (10)\nProfesión:\nIngeniería de Shadowlands (30)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n1\n15\n\n(2)\n[q2]Uso: Lanza un montón de bombas atadas hacia adelante que envuelven al primer enemigo que golpean, explotan después de 5 segundos e infligen 13939 p. de daño de fuego a los enemigos cercanos. (5 Min Reutilización)\nRequiereIngeniería de Shadowlands\n(1)"}
MultiLanguageSpellData['mx'][310490] = {name = "Botas de redistribución de velocidad", additional_info = "Hechizo de 2 seg 3\nHerramientas: Llave de tuerca arcoluz , Martillo de herrero\nComponentes:\nResorte de espiral mortal (10), Puñado de tornillos de lestrita (20), Mena de fedrum (10), Cuero desolado (15), Tela velada (20)\nProfesión:\nIngeniería de Shadowlands (65)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n2\n75\n\nSe liga al usarlo\n[q2]Uso: Redistribuye una parte significativa del daño que recibirías de tu próxima caída a enemigos cercanos. Dura 10 s.\n\n No puede usarse en estancias. (5 Min Reutilización)\nRequiereIngeniería de Shadowlands\n(1)\n[q]\"¡Te permite realizar un aterrizaje superheroico!\""}
MultiLanguageSpellData['mx'][310492] = {name = "Cañón de interferencia gravimétrica", additional_info = "Hechizo de 2 seg 3\nHerramientas: Llave de tuerca arcoluz , Martillo de herrero\nComponentes:\nEngranajes digeridos por gusanos (3), Resorte de espiral mortal (3), Puñado de tornillos de lestrita (20), Abrasivo de pulido poroso (20), Mena de solenio (10), Fragmento sagrado (5)\nProfesión:\nIngeniería de Shadowlands (60)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n2\n50\n\nSe liga al usarlo\n[q2]Uso: Desestabiliza la gravedad en una ubicación seleccionada, lo que entorpece el movimiento de los enemigos cercanos durante 10 s y los lanza por los aires o en cualquier dirección.\n\n A menos que algo salga mal.\nRequiereIngeniería de Shadowlands\n(1)\n[q]\"¡¿Qué?! ¿Cómo que una pistola de agua? Esto es una magnífica pieza de artillería.\""}
MultiLanguageSpellData['mx'][310493] = {name = "TR4MP4-D3-4LM4", additional_info = "Hechizo de 2 seg 3\nHerramientas: Llave de tuerca arcoluz , Martillo de herrero\nComponentes:\nEngranajes digeridos por gusanos (3), Resorte de espiral mortal (5), Puñado de tornillos de lestrita (10), Mena de fedrum (10), Polvo de alma (5)\nProfesión:\nIngeniería de Shadowlands (50)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n2\n\nSe liga al usarlo\n[q2]Uso: Coloca un dispositivo de almacenamiento sobre el suelo que, una vez armado, se activa cuando un enemigo se para encima y lo destierra durante 1 min.\n\n A menos que algo salga mal.\n\n Se reduce el efecto contra jugadores. (3 Min Reutilización)\nRequiereIngeniería de Shadowlands\n(1)\n[q]\"¡¿Con quién te comunicarás?!\""}
MultiLanguageSpellData['mx'][310495] = {name = "Mutador dimensional", additional_info = "Hechizo de 2 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nEngranajes digeridos por gusanos , Puñado de tornillos de lestrita (10), Mena de sinvyr (3), Umbrilio , Fragmento inmortal\n[q]Añade de forma permanente un dispositivo distorsionador de realidad tecnomágico a tu cinturón. Este dispositivo te permite volverte invisible cuando no estás en combate.\nProfesión:\nIngeniería de Shadowlands (45)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n1\n75"}
MultiLanguageSpellData['mx'][310496] = {name = "Electrosalto", additional_info = "Hechizo de 2 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nEngranajes digeridos por gusanos , Puñado de tornillos de lestrita (10), Mena de solenio (3), Orillama , Fragmento inmortal\n[q]Añade de forma permanente un dispositivo manipulador del espacio-tiempo tecnomágico a tu cinturón. Este dispositivo te permite teletransportarte una distancia corta al instante en una dirección aleatoria.\nProfesión:\nIngeniería de Shadowlands (45)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n1\n75"}
MultiLanguageSpellData['mx'][310497] = {name = "Vindicador de daños", additional_info = "Hechizo de 2 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nEngranajes digeridos por gusanos , Puñado de tornillos de lestrita (10), Mena de oxxina (3), Furiojo , Fragmento inmortal\n[q]Añade de forma permanente una matriz de flujo magnético tecnomágica a tu cinturón. Cuando se activa, suspende muchas armas filosas a tu alrededor, lo que inflige daño a los atacantes.\nProfesión:\nIngeniería de Shadowlands (45)\nInstructor:\nMaquinista Au'gur\nZona:\nOribos\nCosto:\n1\n75"}
