MultiLanguageSpellData['mx'][310530] = {name = "Espíritu devoto", additional_info = "Instante\n[q]Cada 5 s, obtienes Espíritu devoto, que hace que tu siguiente Sanación veloz sane 153 p. adicionales y se acumule hasta 3 veces.\n\nÚnico: Aumenta 10 p. la Resistencia a la corrupción."}
