MultiLanguageSpellData['mx'][311408] = {name = "[q2]Códice de los recién fallecidos", additional_info = "Hechizo de 3 seg 2\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nTinta luminosa (10), Tinta umbría (10), Papiro oscuro (50)\nComponentes opcionales:\nModifica el nivel de objeto - Poco (#77)\nProfesión:\nInscripción de Shadowlands (20)\nInstructor:\nEscriba Au'tehshi\nZona:\nOribos\nCosto:\n75\n\n[q2]Códice de los recién fallecidos\nSe liga al equiparlo\nMano izquierda\n+20 intelecto\n+6 aguante\n[q2]+ 4 Estadística aleatoria 1\n[q2]+ 4 Estadística aleatoria 2\nNecesitas ser de nivel 50"}
MultiLanguageSpellData['mx'][311409] = {name = "Contrato: Los Ascendidos", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nTinta luminosa (5), Tinta umbría (5), Papiro oscuro\nVendedora:\nAyudante Mikaros\nZona:\nOribos\nLos Ascendidos - Venerado\nCosto:\n1765\n\nVendedora:\nAyudante Nikos\nZona:\nBastión\nLos Ascendidos - Venerado\nCosto:\n1765\n\n[q2]Uso: Firma un contrato con los Ascendidos que te permitirá ganar reputación con ellos cada vez que completes una misión de mundo en las Tierras de las Sombras.\nNecesitas ser de nivel 51\nRequiereLos Ascendidos\n: Amistoso"}
MultiLanguageSpellData['mx'][311410] = {name = "Contrato: Los Cazadores salvajes", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nTinta luminosa (5), Tinta umbría (5), Papiro oscuro\nVendedora:\nAithlyn\nZona:\nArdenweald\nLos Cazadores salvajes - Venerado\nCosto:\n1765\n\nVendedora:\nLiawyn\nZona:\nOribos\nLos Cazadores salvajes - Venerado\nCosto:\n1765\n\n[q2]Uso: Firma un contrato con los Cazadores salvajes que te permitirá ganar reputación con ellos cada vez que completes una misión de mundo en las Tierras de las Sombras.\nNecesitas ser de nivel 51\nRequiereCazadores salvajes\n: Amistoso"}
MultiLanguageSpellData['mx'][311411] = {name = "Contrato: El Ejército Inmortal", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nTinta luminosa (5), Tinta umbría (5), Papiro oscuro\nVendedora:\nDar Vattish\nZona:\nOribos\nEl Ejército Inmortal - Venerado\nCosto:\n1765\n\nVendedor:\nNalcorn Talsen\nZona:\nMaldraxxus\nEl Ejército Inmortal - Venerado\nCosto:\n1765\n\n[q2]Uso: Firma un contrato con el Ejército Inmortal que te permitirá ganar reputación con ellos cada vez que completes una misión de mundo en las Tierras de las Sombras.\nNecesitas ser de nivel 51\nRequiereEl Ejército Inmortal\n: Amistoso"}
