MultiLanguageSpellData['mx'][311423] = {name = "[q2]Escrito del asalto de tumbas", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nTinta luminosa , Tinta umbría , Papiro oscuro\nProfesión:\nInscripción de Shadowlands (10)\nInstructor:\nEscriba Au'tehshi\nZona:\nOribos\nCosto:\n30\n\n[q2]Escrito del asalto de tumbas\n[q2]Uso: Permite abrir cerraduras que requieren hasta 60 p. de habilidad de forzar cerraduras. El pergamino se consume durante el proceso.\nNecesitas ser de nivel 51\nRequiereInscripción de Shadowlands\n(1)"}
MultiLanguageSpellData['mx'][311424] = {name = "[q2]Códice de la mente serena", additional_info = "Hechizo de 2 seg\nHerramientas: Juego de caligrafía de virtuoso\nComponentes:\nTinta luminosa (7), Tinta umbría (7), Tinta serena , Papiro oscuro (75)\nVendedora:\nAyudante Mikaros\nZona:\nOribos\nLos Ascendidos - Amistoso\nCosto:\n8\n\nVendedora:\nAyudante Nikos\nZona:\nBastión\nLos Ascendidos - Amistoso\nCosto:\n8\n\n[q2]Códice de la mente serena\n[q2]Uso: Prepara un códice que permite a los jugadores cercanos ajustar sus talentos.\nNecesitas ser de nivel 51\n[q]\"Lo crean los jugadores con habilidad en inscripción. Se puede comprar y vender en la casa de subastas.\""}
