MultiLanguageSpellData['mx'][312749] = {name = "Aligerar", additional_info = "[q0][Covenant Ability]Hechizo de 1.5 seg 2 min de reutilización\n[q]Te disuelves en ánima pura, lo que aumenta tu velocidad de movimiento al 300%, reduce tu velocidad de caída y te impulsa durante 4 s.\n\n Reduce notablemente el radio en el que los enemigos pueden detectarte."}
MultiLanguageSpellData['mx'][312750] = {name = "Extraer pesadilla", additional_info = "Rango ilimitado\nCanalizado (Hechizo de 1 min)\n[q]La Pesadilla conjurada busca a su creador para transmitirle su poder."}
MultiLanguageSpellData['mx'][312751] = {name = "Yugo de Ha-Li", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"La camada de Ha-Li se siente a gusto cazando presas desprevenidas en los cielos azules de Pandaria.\"\nBotín:\nHa-Li\nZona:\nValle de la Flor Eterna"}
MultiLanguageSpellData['mx'][312752] = {name = "Congelamiento", additional_info = "Alcance de 20 m\nInstante\n[q]Aplica Triza de escarcha cada 6 s."}
MultiLanguageSpellData['mx'][312753] = {name = "Gargon aplastaesperanzas", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Esta montura alguna vez le fue fiel a un señor de la Casa Espantazarza, pero finalmente los traicionó a él y a su comitiva. Ahora, los miembros de la Casa Espantazarza susurran sobre un gargon oscuro que espera o incluso provoca a los venthyr que se internan en las áreas más oscuras del Distrito Cáliz en Revendreth.\"\nPacto:\nVenthyr\nZona:\nRevendreth"}
MultiLanguageSpellData['mx'][312754] = {name = "Gargon de batalla Vrednic", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El fiel gargon del príncipe Renathal, Vrednic, ha estado a su lado durante milenios. Cubierto con su armadura de sinvyr, la sola presencia de Vrednic infunde terror en todos los que lo avistan cuando lleva a su jinete a la batalla.\"\nPacto:\nVenthyr\nZona:\nRevendreth"}
MultiLanguageSpellData['mx'][312756] = {name = "PH Phalynx", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura."}
MultiLanguageSpellData['mx'][312758] = {name = "PH Epic Phalynx", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura."}
MultiLanguageSpellData['mx'][312759] = {name = "Venado rúnico luz onírica", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Les conceden venados rúnicos a quienes han jurado servir a la Reina del invierno y la Corte de la Noche.\"\nPacto:\nNoctifeéricos\nZona:\nArdenweald"}
MultiLanguageSpellData['mx'][312761] = {name = "Venado rúnico luz onírica encantado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los venados rúnicos majestuosos tienen la capacidad de succionar ánima de la luz ambiental de Ardenweald con sus astas complejas. El ánima sirve como nutrición y como energía para la velocidad y la magia del venado rúnico.\"\nPacto:\nNoctifeéricos\nZona:\nArdenweald"}
MultiLanguageSpellData['mx'][312762] = {name = "Cazador de almas jurafauces", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los cazadores de almas están acostumbrados a rastrear almas rebeldes que huyen de sus destinos oscuros a través de los páramos, y son unas de las pocas criaturas que se sienten a gusto recorriendo las Fauces.\"\nBotín:\nSabueso sombrío atiborrado\nZona:\nLas Fauces"}
MultiLanguageSpellData['mx'][312763] = {name = "Durazón madriscura", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"La quitina del durazón madriscura es tan resistente que puede soportar disparos de mortero y fuego de dragón. Convenientemente, también consume todo lo que no tenga ánima, de ser necesario.\"\nAventuras:\nShadowlands"}
MultiLanguageSpellData['mx'][312764] = {name = "Réplica de conocimiento", additional_info = "Alcance de 40 m\n[q]Ahora Réplica de conocimiento puede copiar hasta el rango 2 de la esencia principal actual de tu objetivo, y el tiempo de reutilización más largo se reduce un 10%."}
MultiLanguageSpellData['mx'][312765] = {name = "Helios", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Este trotador bañado por el sol galopa sobre rayos de luz muy despreocupadamente.\"\nBotín:\nZona:\nBastión"}
