MultiLanguageSpellData['mx'][312776] = {name = "Animácaro estridente", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Estas criaturas voladoras excepcionalmente ágiles son excelentes monturas después de entrenarlas para que no succionen hasta la última gota de ánima de sus jinetes.\"\nAventuras:\nTierras de las Sombras"}
MultiLanguageSpellData['mx'][312777] = {name = "Alatemible colargenta", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Criados por el príncipe de Revendreth, Renathal, estos alatemibles inusuales son terriblemente leales y solo permitirán que aquellos juzgados dignos por el príncipe interactúen con ellos.\"\nFunción de Pacto:\nLa Corte de Brasas\nPacto:\nVenthyr\n\nFunción de Pacto:\nVivero de la Reina\nPacto:\nNoctifeéricos\n\nFunción de Pacto:\nSenda de Ascensión\nPacto:\nKyrian\n\nFunción de Pacto:\nFábrica de Abominaciones\nPacto:\nNecroseñores"}
