MultiLanguageSpellData['mx'][312945] = {name = "¡Acto 2, empiecen!", additional_info = "Instante\n[q]¡Comienza el acto 2!"}
MultiLanguageSpellData['mx'][312946] = {name = "Espíritus afines", additional_info = "[q0][Covenant Ability]Instante\n[q]Forma un lazo con un aliado. Cada 1 min, puedes potenciar el lazo durante 10 s para obtener un efecto según el rol de tu compañero y otorgarle a él un efecto según tu rol.\n\n [ Guardián : Tanque\n Protección afín\nProtege a tu compañero enlazado y sufres un 40% del daño que recibe en su lugar, a menos que estés por debajo del 20% de salud. ] [ Restauración : Sanador\n Enfoque afín\nTe concentras en tu compañero enlazado y replicas un 30% de toda la sanación que realizas sobre él. /\n\nEquilibrio, Feral\nInfligidor de daño\n Potenciamiento afín\nEnergiza a tu compañero enlazado y le otorga un 20% de tu daño como sanación, absorción o daño arcano adicional. ]"}
MultiLanguageSpellData['mx'][312947] = {name = "Flecha resonante", additional_info = "[q0][Covenant Ability]Instante\n[q]Dispara una flecha resonante a la ubicación objetivo que inflige ([20% of Attack Power]) p. de daño arcano a cualquier enemigo en el área y llena el área con ánima resonante durante 10 s. El efecto hace que tus ataques ignoren la necesidad de tener visión de los enemigos en el área, y tienes un 30% más de probabilidad de golpe crítico contra ellos.\n\n Después de abandonar el área de ánima resonante, aún puedes atacar enemigos sin que estén dentro de tu campo visual durante 4 s."}
MultiLanguageSpellData['mx'][312950] = {name = "Chispa radiante", additional_info = "[q0][Covenant Ability]Instante\n[q]Conjura una chispa radiante que inflige ([91.2% of Spell Power]) p. de daño arcano de forma instantánea y ([49.5% of Spell Power]) p. más de daño durante 10 s.\n\n El objetivo recibe un 10% más de daño de tus hechizos de daño directos, y se acumula cada vez que los golpean. Este efecto termina después de 4 hechizos."}
MultiLanguageSpellData['mx'][312951] = {name = "Armas de orden", additional_info = "[q0][Covenant Ability]Instante\n[q]Maestro cervecero\nDurante los próximos 30 s, tu maestría aumenta un ( 0.924000025 * 10)%. Además, El tiempo de reutilización de Embate con barril se restablece al instante y los enemigos golpeados por Embate con barril reciben un 8% más de daño de ti durante 10 s. Este efecto se acumula hasta 4 veces.\n\nViajero del viento\nDurante los próximos 30 s, tu maestría aumenta un ( 2.3287499 * 10)%. Además, Patada del sol naciente reduce los costos de chi 1 p. durante 5 s, y Patada oscura reduce 1 s más el tiempo de reutilización de las habilidades afectadas.\n\nTejedor de niebla\nDurante los próximos 30 s, tu maestría aumenta un ( 6.92999983 * 10)%. Además, El tiempo de reutilización de Fuente de esencia se restablece al instante y sana ([40% of Spell Power]) p. de salud a un máximo de 6 aliados cercanos al comienzo y término de la canalización."}
MultiLanguageSpellData['mx'][312952] = {name = "Tañido divino", additional_info = "[q0][Covenant Ability]Instante\n[q]Lanza al instante Choque sagrado, Escudo de vengador o Sentencia a un máximo de 5 objetivos en un radio de 30 m (según tu especialización actual). [ Reprensión : La Sentencia de Tañido divino inflige un 100% más de daño ]"}
MultiLanguageSpellData['mx'][312953] = {name = "Favor de los ascendidos", additional_info = "[q0][Covenant Ability]Instante\n[q]Utiliza el poder de los ascendidos durante 10 s. Obtienes acceso a Nova ascendida , [ Sombra : Tortura mental /\n\nDisciplina, Sagrado\nPunición ] se reemplaza por Ráfaga ascendida y aumenta un 50% tu velocidad de movimiento.\n\n Cuando expira, libera una Erupción ascendida :\n\nExplota e inflige hasta ([210% of Spell Power]) p. de daño arcano a los enemigos y sana ([159% of Spell Power]) p. a los aliados en un radio de 15 m, según la cantidad de enemigos. El daño y la sanación aumentan un 3% por cada acumulación de Favor de los ascendidos."}
MultiLanguageSpellData['mx'][312954] = {name = "Reprimenda resonante", additional_info = "[q0][Covenant Ability]Instante\n[q]Inflige ([120% of Attack Power]) p. de daño arcano a un enemigo y extrae su ánima para cargar con ánima un punto de combo durante 45 s.\n\n Los remates que infligen daño y consumen la misma cantidad de puntos de combo que tu habilidad de cargar con ánima funcionan como si consumieran 7 puntos de combo.\n\nOtorga 2 puntos de combo."}
MultiLanguageSpellData['mx'][312955] = {name = "Tótem de carillón", additional_info = "[q0][Covenant Ability]Instante\n[q]Invoca un tótem en la ubicación objetivo durante 30 s. Tus próximos 3 hechizos o habilidades de daño harán que el tótem irradie ([80% of Spell Power]) p. de daño arcano a un máximo de 6 enemigos cercanos, y tus próximos 3 hechizos de sanación sanarán ([91% of Spell Power]) p. de salud a un máximo de 6 aliados cercanos al tótem.\n\n Lanzar esta habilidad nuevamente mientras el tótem está activo reubicará el tótem."}
MultiLanguageSpellData['mx'][312956] = {name = "Diezmo arrasador", additional_info = "[q0][Covenant Ability]Instante\n[q]Inflige ([65% of Spell Power]) p. de daño arcano al instante y ([108% of Spell Power]) p. durante 18 s. Si el enemigo muere mientras está bajo el efecto de Diezmo arrasador, generas [ Aflicción : 5 / Demonología : 5 /\n\nDestrucción\n5 ] Fragmentos de alma. Si sobrevive, el tiempo de reutilización de Diezmo arrasador se restablece."}
MultiLanguageSpellData['mx'][312957] = {name = "Lanza de Bastión", additional_info = "[q0][Covenant Ability]Instante\n[q]Arroja una lanza kyriana a la ubicación objetivo que inflige ([110% of Attack Power]) p. de daño arcano al instante y ([120% of Attack Power]) p. de daño más durante 4 s. Inflige daño reducido contra más de 5 objetivos.\n\n Los enemigos que golpea quedan atados a la ubicación de la Lanza de Bastión hasta que termine el efecto.\n\nGenera 25 p. de ira."}
