MultiLanguageSpellData['mx'][314270] = {name = "Plegaria atendida", additional_info = "[q0][Anima Power]Instante\n[q]Fe ciega ya no tiene efectos negativos cuando expira. En su lugar, explotas con energía arcana, infliges ([480% of Spell Power]) p. de daño a los enemigos y sanas ([480% of Spell Power]) p. de salud a los aliados en un radio de 12 m."}
