MultiLanguageSpellData['mx'][314959] = {name = "Vacialetas al horno", additional_info = "Hechizo de 2 seg\nComponentes:\nVacialetas aberrante (8), Carne dudosa (3), Aceite de pescado aromático (3), Harina salvaje (4)\n[q]Prepara un Vacialetas al horno.\nBotín:\nCultistas de N'Zoth\n\n(5)\n[q2]Uso: Restaura 50769 p. de salud y 30769 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 segundos, quedarás bien alimentado.\n\n Mientras estás bien alimentado, la velocidad de movimiento aumenta un 20% cuando estás en una Visión de N'Zoth."}
MultiLanguageSpellData['mx'][314960] = {name = "K'bab", additional_info = "Hechizo de 2 seg\nComponentes:\nCarne dudosa (8), Rechinador deforme (5), Vacialetas aberrante (3), Aceite de pescado aromático (3)\n[q]Preparar K'bab.\nBotín:\nCultistas de N'Zoth\n\n(5)\n[q2]Uso: Restaura 50769 p. de salud y 30769 p. de maná durante 20 s. Debes permanecer sentado mientras comes.\n\n Si comes durante al menos 10 segundos, se restauran instantáneamente 100 p. de cordura. (3 Min Reutilización)"}
MultiLanguageSpellData['mx'][314961] = {name = "Delicia dudosa", additional_info = "Hechizo de 2 seg\nComponentes:\nCarne dudosa (8), Aceite de pescado aromático (3), Harina salvaje (3), Patata fresca (4)\n[q]Prepara una Delicia dudosa.\nBotín:\nCultistas de N'Zoth\n\n(5)\n[q2]Uso: Restaura 50769 p. de salud y 30769 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 segundos, quedarás bien alimentado.\n\n Mientras estés bien alimentado, se reduce un 20% la duración de los próximos efectos de control de masas cuando estás en una Visión de N'Zoth."}
MultiLanguageSpellData['mx'][314962] = {name = "Estofado espeluznante", additional_info = "Hechizo de 2 seg\nComponentes:\nCarne dudosa (8), Vacialetas aberrante (5), Rechinador deforme (3), Aceite de pescado aromático (3)\n[q]Prepara un Estofado espeluznante.\nBotín:\nCultistas de N'Zoth\n\n(5)\n[q2]Uso: Restaura 50769 p. de salud y 30769 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 segundos, quedarás bien alimentado.\n\n Mientras estés bien alimentado, se regenera un 2% de tu salud máxima por segundo cuando estás en una Visión de N'Zoth."}
MultiLanguageSpellData['mx'][314963] = {name = "Rechinador grillado", additional_info = "Hechizo de 2 seg\nComponentes:\nRechinador deforme (8), Carne dudosa (3), Aceite de pescado aromático (3), Fusaka (4)\n[q]Prepara un Rechinador grillado.\nBotín:\nCultistas de N'Zoth\n\n(5)\n[q2]Uso: Restaura 50769 p. de salud y 30769 p. de maná durante 20 s. Debes permanecer sentado mientras comes. Si comes durante al menos 10 s, estarás bien alimentado.\n\n Mientras estás bien alimentado, asumes la forma de un k'thir, lo que reduce el rango de ataque de los enemigos mientras estás en una Visión de N'Zoth durante 10 min."}
