MultiLanguageSpellData['mx'][320660] = {name = "Herramientas de Niya: Veneno", additional_info = "[q0][Soulbind Ability][q]Tus interrupciones aplican Veneno paralizador de Niya a tu objetivo, lo que inflige [(Poder de ataque * 0.05 * (1 + Versatilidad)) * 30] p. de daño de naturaleza durante 30 s. Los objetivos de Veneno paralizador de Niya reciben [Poder de ataque * 0.24 * (1 + Versatilidad)] p. de daño de naturaleza más si se produce otra interrupción."}
MultiLanguageSpellData['mx'][320661] = {name = "Arremeter", additional_info = "Rango ilimitado\nInstante\n[q]Cuando su energía llega a 100 p., Xav obliga a los jugadores a entrar al foso de duelos de abajo. El ganador del duelo obtiene Glorificado , y el perdedor queda bajo los efectos de Ensangrentado .\n\n Los jugadores obtienen una acumulación de Combate glorioso cada 1 s.\n\n ^Si ningún jugador resulta derrotado en 45 s, los dos jugadores quedan bajo los efectos de Cobardía ."}
MultiLanguageSpellData['mx'][320662] = {name = "Herramientas de Niya: Hierbas", additional_info = "[q0][Soulbind Ability][q]Tus hechizos y habilidades de sanación tienen una probabilidad de aplicar Hierbas vigorizantes de Niya, lo que aumenta la celeridad del objetivo un 5% durante 10 s.\n(Probabilidad de que accione: 30%, 10s de reutilización)"}
