MultiLanguageSpellData['mx'][320871] = {name = "Celo del vándalo", additional_info = "[q0][Anima Power]Instante\n[q]Destruir un objeto destruible en Torghast potencia tu [ Sagrado : Fuego sagrado /\n\nDisciplina, Sombra\nExplosión mental ] un 3%. Se acumula hasta 40 veces."}
MultiLanguageSpellData['mx'][320872] = {name = "[q3]Acumulación de relámpago", additional_info = "[q0][Anima Power]Instante\n[q]Por cada 30 segundos que pasan sin que lances Sanación relámpago, la sanación de tu próxima Sanación relámpago aumenta un 100%. Este efecto puede acumularse hasta 6 veces."}
MultiLanguageSpellData['mx'][320873] = {name = "Farol abrasador", additional_info = "[q0][Anima Power]Instante\n[q]Tus Sanaciones relámpago aplican Luminosidad abrasadora a tus objetivos y hacen que reflejen un 50% del daño que reciben nuevamente a sus atacantes como daño sagrado durante 20 s."}
MultiLanguageSpellData['mx'][320874] = {name = "Bendición del sacerdote caído", additional_info = "[q0][Anima Power]Instante\n[q]Disciplina\n Lanzar Explosión mental aumenta el daño o la sanación de tu siguiente Penitencia un 30%. Este efecto se acumula, pero la duración no se restablece.\n\nSombra\n Lanzar Explosión mental aumenta el daño o la sanación de tu siguiente Peste devoradora un 30%. Este efecto se acumula, pero la duración no se restablece.\n\nSagrado\n Lanzar Fuego sagrado aumenta el daño o la sanación de tu siguiente Palabra sagrada: Condena un 60%. Este efecto se acumula, pero la duración no se restablece.\n(100ms de reutilización)"}
