MultiLanguageSpellData['mx'][323913] = {name = "Carne reverberante", additional_info = "[q]Cuando recibes una sanación o sanas a tus aliados, obtienes un 1% de golpe crítico durante 10 s, hasta un máximo de 5%.\n\n Cuando estás potenciado por hueso inscrito con runas, obtienes un 1% más de golpe crítico por acumulación.\n(1s de reutilización)"}
MultiLanguageSpellData['mx'][323914] = {name = "Hilotajo", additional_info = "[q]Tus ataques y hechizos tienen una probabilidad de materializar cuchillas giratorias a tu alrededor, que aplican un sangrado que inflige 500 p. de daño durante 5 s.\n\n Cuando estás potenciado por hueso inscrito con runas, el daño se duplica."}
