MultiLanguageSpellData['mx'][330897] = {name = "[q2]Zarcillos enredadores", additional_info = "[q0][Anima Power]Instante\n[q]Los primeros 3 ataques cuerpo a cuerpo con Piel de corteza o Corteza de hierro, aplicarán Raíces enredadoras al atacante."}
MultiLanguageSpellData['mx'][330898] = {name = "Puños de furia", additional_info = "Alcance de 8 mCanalizado (Hechizo de 3 seg) 24 seg de reutilización\n[q]Zurras a todos los objetivos frente a ti, infliges [5 * ([120.75% of Attack Power])] p. de daño físico durante 3 s a tu objetivo principal y [5 * ([120.75% of Attack Power]) * 50 / 100] p. de daño durante 3 s a un máximo de 5 objetivos más."}
MultiLanguageSpellData['mx'][330901] = {name = "Patada giratoria de la grulla", additional_info = "{2 de chi / 1% del maná base} {/ 25 p. de energía}\nCanalizado (Hechizo de 1.5 seg)\n[q]Viajero del viento\n Giras mientras das patadas en el aire e infliges [4 * ([10% of Attack Power]) * [(Poder de ataque * 0.98)][((Poder de ataque + [Offhand Attack Power]) * 2 / 3)] -- 2H, DW / Poder de ataque] p. de daño físico durante 1.5 s a un máximo de 6 enemigos en un radio de 8 m.\n\n El daño de Patada giratoria de la grulla aumenta un 18% por cada objetivo único golpeado en los últimos 20 s con Palma del tigre, Patada oscura o Patada del sol naciente.\n\nMaestro cervecero, Tejedor de niebla\n Giras mientras das patadas en el aire e infliges [4 * ([10% of Attack Power])] p. de daño físico durante 1.5 s a un máximo de 6 enemigos en un radio de 8 m."}
MultiLanguageSpellData['mx'][330902] = {name = "Teletransporte a la cima", additional_info = nil}
MultiLanguageSpellData['mx'][330903] = {name = "Patada giratoria de la grulla", additional_info = "Instante\n[q]Viajero del viento\nGiras mientras das patadas en el aire e infliges [4 * ([10% of Attack Power]) * [(Poder de ataque * 0.98)][((Poder de ataque + [Offhand Attack Power]) * 2 / 3)] -- 2H, DW / Poder de ataque] p. de daño físico durante 1.5 s a todos los enemigos en un radio de 8 m. Inflige menos daño cuando golpea a más de 5 objetivos.\n\nMaestro cervecero, Tejedor de niebla\nGiras mientras das patadas en el aire e infliges [4 * ([10% of Attack Power])] p. de daño físico durante 1.5 s a todos los enemigos en un radio de 8 m. Inflige menos daño cuando golpea a más de 5 objetivos."}
MultiLanguageSpellData['mx'][330904] = {name = "[q2]Escarabajo de maderaíz", additional_info = "[q0][Anima Power]Instante\n[q]Cuando Raíces enredadores se quiebra, explota e inflige ([150% of Spell Power]) p. de daño de naturaleza a todos los enemigos cercanos."}
