MultiLanguageSpellData['mx'][330910] = {name = "Carne de cañón para la llama", additional_info = "Alcance de 100 m\nInstante\n[q]Tus habilidades que infligen daño tienen una probabilidad de invocar un demonio del Teatro del Dolor durante 25 s. Lanzar guja inflige daño letal al demonio, que explota al morir e inflige ([192.5% of Attack Power]) p. de daño de las sombras a los enemigos cercanos y te sana un 20% de tu salud máxima. La explosión inflige menos daño después de afectar a 5 objetivos."}
MultiLanguageSpellData['mx'][330911] = {name = "Embate con barril", additional_info = "Alcance de 15 m\n{Instante} {8 seg de reutilización}\n1 carga\n[q]Golpea al objetivo con un barril de brebaje que inflige ([99.9% of Attack Power]) p. de daño físico a todos los enemigos en un radio de 8 m y reduce su velocidad de movimiento un 20% durante 15 s. Inflige menos daño cuando afecta a más de 5 objetivos.\n\nMaestro cervecero\n[q]Grants Shuffle for 5 sec and reduces the remaining cooldown on your Brews by 3 sec."}
