MultiLanguageSpellData['mx'][332456] = {name = "Tauralus pestilente", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El tauralus es considerado una criatura intrépida, aunque hace tiempo que los eruditos de Maldraxxus se preguntan si la falta de temor se debe al pequeño tamaño de su cerebro.\"\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
MultiLanguageSpellData['mx'][332457] = {name = "Tauralus pezuñaósea", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Sobran motivos por los que uno debería evitar pararse detrás de un tauralus. Las pezuñas y las colas que parecen látigos están al final de la lista.\"\nBotín:\nTahonta\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
