MultiLanguageSpellData['mx'][335931] = {name = "Estandarte del conquistador", additional_info = "[q0][Covenant Ability]Instante\n[q]Enarbola el Estandarte del conquistador, lo que otorga 1550 p. de maestría y un 30% más de velocidad de movimiento a ti y a tus 2 aliados más cercanos, además de impedir que se reduzca la velocidad de movimiento por debajo del 100%. Dura 15 s.\n\nGenera 4 p. de ira por segundo."}
MultiLanguageSpellData['mx'][335932] = {name = "Chakram de la muerte", additional_info = "[q0][Covenant Ability]Instante\n[q]Arrojas un chakram mortal a tu objetivo actual que inflige rápidamente ([31.6% of Attack Power]) p. de daño de las sombras 7 veces y rebota a otros objetivos si están cerca. Los enemigos golpeados por Chakram de la muerte reciben un 10% más de daño físico de ti y tu mascota durante 10 s.\n\n Cada vez que el chakram daña a un objetivo, inflige un 15% más de daño y tú generas 3 p. de Enfoque."}
MultiLanguageSpellData['mx'][335933] = {name = "Extremidad de abominación", additional_info = "[q0][Covenant Ability]Instante\n[q]Sangre\nTe brota una extremidad adicional que inflige [([28.4% of Attack Power]) * 13] p. de daño de las sombras durante 12 s a todos los enemigos cercanos. Inflige menos daño cuando golpea a más de 5 objetivos. Cada 1 s, atrae a un enemigo a tu ubicación si está a más de 8 m de ti. Se puede atraer al mismo enemigo una vez cada 4 s.\n\n Obtienes 3 cargas de Escudo óseo al instante, y otra vez cada 6 s.\n\nProfano\nTe brota una extremidad adicional que inflige [([28.4% of Attack Power]) * 13] p. de daño de las sombras durante 12 s a todos los enemigos cercanos. Inflige menos daño cuando golpea a más de 5 objetivos. Cada 1 s, atrae a un enemigo a tu ubicación si está a más de 8 m de ti. Se puede atraer al mismo enemigo una vez cada 4 s.\n\n Obtienes Corrupción rúnica al instante, y otra vez cada 6 s.\n\nEscarcha\nTe brota una extremidad adicional que inflige [([28.4% of Attack Power]) * 13] p. de daño de las sombras durante 12 s a todos los enemigos cercanos. Inflige menos daño cuando golpea a más de 5 objetivos. Cada 1 s, atrae a un enemigo a tu ubicación si está a más de 8 m de ti. Se puede atraer al mismo enemigo una vez cada 4 s.\n\n Obtienes Helada blanca al instante, y otra vez cada 6 s."}
MultiLanguageSpellData['mx'][335934] = {name = "Carne de cañón para la llama", additional_info = "[q0][Covenant Ability]Instante\n[q]Tus habilidades que infligen daño tienen una probabilidad de invocar un demonio del Teatro del Dolor durante 25 s. Lanzar guja inflige daño letal al demonio, que explota al morir e inflige ([192.5% of Attack Power]) p. de daño de las sombras a los enemigos cercanos y te sana un 20% de tu salud máxima. La explosión inflige menos daño después de afectar a 5 objetivos."}
MultiLanguageSpellData['mx'][335935] = {name = "Enjambre adaptable", additional_info = "[q0][Covenant Ability]Instante\n[q]Envía un enjambre que sana ([157.5% of Spell Power]) p. o inflige ([150% of Spell Power]) p. de daño de las sombras durante 12 s a un objetivo y aumenta un 25% la efectividad de tus efectos periódicos sobre ese objetivo.\n\n A su término, encuentra un nuevo objetivo. Preferentemente, alterna entre aliados y enemigos hasta 3 veces."}
MultiLanguageSpellData['mx'][335936] = {name = "Nacido de la muerte", additional_info = "[q0][Covenant Ability]Instante\n[q]Te transformas en un mago esquelético poderoso durante 25 s.\n\n En la forma de mago esquelético, tu Descarga de escarcha, Bola de fuego y Explosión arcana golpean a un máximo de 2 enemigos cerca de tu objetivo y tu daño con hechizos aumenta un 15%."}
MultiLanguageSpellData['mx'][335937] = {name = "Brebaje de polvo de hueso", additional_info = "[q0][Covenant Ability]Instante\n[q]Lanza al suelo un brebaje creado con los huesos de tus enemigos, y cubre a todos los objetivos golpeados durante 10 s. Tus habilidades tienen un 50% de probabilidad de afectar al objetivo una segunda vez con un 40% de efectividad como daño de las sombras o sanación.\n\n [ Tejedor de niebla : Ráfaga de niebla sana ([42% of Attack Power]) p. más de salud a los objetivos afectados por tu Brebaje de polvo de hueso / Maestro cervecero : Palma del tigre y Embate con barril reducen el tiempo de reutilización de tus brebajes otros 1 s cuando golpean enemigos afectados por tu Brebaje de polvo de hueso / Viajero del viento : Patada giratoria de la grulla restituye 1 p. de chi cuando golpea enemigos afectados por tu Brebaje de polvo de hueso ]"}
MultiLanguageSpellData['mx'][335938] = {name = "Pulso congelante", additional_info = "Instante\n[q]Mort despide baba congelante cada 5 s e inflige 0 de daño de escarcha y aplica Extremidades congeladas a enemigos en un radio de 10 m y deja un área de Tierra helada."}
MultiLanguageSpellData['mx'][335939] = {name = "Martillo del vencedor", additional_info = "[q0][Covenant Ability]Instante\n[q]Lanza un martillo a tu objetivo que inflige ([136% of Spell Power]) p. de daño de las sombras y potencia tu siguiente [ Reprensión : Veredicto del templario para que active Tormenta divina automáticamente ] [ Sagrado : Palabra de gloria para que active Luz del alba automáticamente /\n\nProtección\nPalabra de gloria para que active Escudo del honrado automáticamente ] con un 25% más de efectividad.\n\nGenera 1 p. de poder sagrado."}
MultiLanguageSpellData['mx'][335940] = {name = "Púa ósea serrada", additional_info = "[q0][Covenant Ability]Instante\n[q]Incrusta una púa ósea en el objetivo, inflige ([132% of Attack Power]) p. de daño físico y ([11% of Attack Power]) p. de daño de sangrado cada 3 s hasta que muere o sale de combate.\n\n Restaura una carga cuando el objetivo muere.\n\nOtorga 1 p. de combo más 1 adicional por cada púa ósea activa."}
MultiLanguageSpellData['mx'][335941] = {name = "Ola primordial", additional_info = "[q0][Covenant Ability]Instante\n[q]Restauración\nGolpea a tu objetivo con una Ola primordial que inflige ([65% of Spell Power]) p. de daño de las sombras y aplica Choque de llamas a un enemigo, o restablece ([65% of Spell Power]) p. de salud a un aliado y le aplica Mareas vivas.\n\n Tu siguiente Ola de sanación también se aplicará a todos los objetivos afectados por tu Mareas vivas, que recibirán un 60% de sanación normal.\n\nMejora\nGolpea a tu objetivo con una Ola primordial que inflige ([65% of Spell Power]) p. de daño de las sombras y aplica Choque de llamas a un enemigo, o restablece ([65% of Spell Power]) p. de salud a un aliado.\n\n Tu siguiente Descarga de relámpagos también se aplicará a todos los objetivos afectados por tu Choque de llamas, que recibirán un 150% de daño normal.\n\nElemental\nGolpea a tu objetivo con una Ola primordial que inflige ([65% of Spell Power]) p. de daño de las sombras y aplica Choque de llamas a un enemigo, o restablece ([65% of Spell Power]) p. de salud a un aliado.\n\n Tu siguiente Ráfaga de lava también se aplicará a todos los objetivos afectados por tu Choque de llamas, que recibirán un 80% de daño normal."}
MultiLanguageSpellData['mx'][335942] = {name = "Descarga exterminadora", additional_info = "[q0][Covenant Ability]Instante\n[q]Demonología, Demonología (Brujo de destrucción)\nLanza descargas de magia exterminadora a tu objetivo, inflige [4 * ([34.5% of Spell Power])] p. de daño de las sombras y aumenta el daño de tus próximos 3 lanzamientos de Descargas demoníacas un 100%.\n\n El daño de Descarga exterminadora y la bonificación de Descarga demoníaca aumentan a medida que la salud de tu objetivo disminuye.\n\nDestrucción, Destrucción (Brujo de demonología)\nLanza descargas de magia exterminadora a tu objetivo, inflige [4 * ([34.5% of Spell Power])] p. de daño de las sombras y aumenta el daño de tus próximos 3 lanzamientos de Incinerar un 100%.\n\n El daño de Descarga exterminadora y la bonificación de Incinerar aumentan a medida que la salud de tu objetivo disminuye.\n\nAflicción\nLanza descargas de magia exterminadora a tu objetivo, inflige [4 * ([34.5% of Spell Power])] p. de daño de las sombras y aumenta el daño de tus próximos 3 lanzamientos de un 100%.\n\n El daño de Descarga exterminadora y la bonificación de aumentan a medida que la salud de tu objetivo disminuye."}
