MultiLanguageSpellData['mx'][336005] = {name = "Graznido rompetímpanos", additional_info = "Alcance de 200 m\nInstante\n[q]Alachillona inflige 29628 p. de daño sónico a todos los jugadores en su línea de visión y 7111 p. más de daño sónico cada 2 s durante 12 s. Los jugadores también dejan un Icor sanguino en su ubicación."}
MultiLanguageSpellData['mx'][336006] = {name = "Cólera de la Reina", additional_info = "Instante\n[q]Arroja el frasco de fuego líquido, inflige una cantidad de daño equivalente al 5% de salud como daño de fuego y aturde a todas las abominaciones de mimbre que están en un radio de 5 m de la zona de impacto durante 5 s. Además, inflige una cantidad de daño de fuego equivalente al 2% de salud."}
MultiLanguageSpellData['mx'][336007] = {name = "Ira humeante", additional_info = "Rango ilimitado\nInstante\n[q]En dificultad heroica y superior, Delicadeza fatal deja una esfera de ánima volátil que explota después de 10 s e inflige hasta 71107 p. de daño de las sombras a todos los jugadores.\n\n Cada (7 / 10) s, la esfera inflige 4740 p. de daño de las sombras a los jugadores que están en un radio de 3 m. El daño infligido de esa manera luego se descuenta del daño de la explosión final."}
MultiLanguageSpellData['mx'][336008] = {name = "Ira humeante", additional_info = "Rango ilimitado\nInstante\n[q]En dificultad heroica y superior, Delicadeza fatal deja una esfera de ánima volátil que explota después de 10 s e inflige hasta 71107 p. de daño de las sombras a todos los jugadores.\n\n Cada (7 / 10) s, la esfera inflige 4740 p. de daño de las sombras a los jugadores que están en un radio de 3 m. El daño infligido de esa manera luego se descuenta del daño de la explosión final."}
