MultiLanguageSpellData['mx'][336036] = {name = "Colmituétano", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Colmituétano, la progenie de Colmihueso, era respetada por Amarth, el Cosechador, por su apetito insaciable, incluso si interrumpía alguno de los experimentos que el comandante quería llevar a cabo.\"\nBotín:\nNalthor Friogénesis\nZona:\nLa Destrucción Necrótica (Mítico)\n\nBotín:\nAlijo del Contendiente\nZona:\nLa Destrucción Necrótica"}
MultiLanguageSpellData['mx'][336037] = {name = "Filo del Olvido", additional_info = "Alcance de 10 m\nHechizo de 2 seg\n[q]Ataca a todos los enemigos en un cono y les inflige daño físico."}
MultiLanguageSpellData['mx'][336038] = {name = "Alaflagelada inmaduro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los alaflageladas son una fuerza necesaria en el ciclo de vida de las Tierras de las Sombras. Son presas y también depredadores en el duro entorno de Maldraxxus.\"\nZona:\nMaldraxxus"}
MultiLanguageSpellData['mx'][336039] = {name = "Alaflagelada horripilante", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los alaflageladas de Maldraxxus son muy valorados por su habilidad de surcar los cielos de las Tierras de las Sombras como si no les implicara esfuerzo alguno, lo que le permite al jinete concentrarse en atacar a sus enemigos o ayudar a sus aliados.\"\nFunción de Pacto:\nLa Corte de Brasas\nPacto:\nVenthyr\n\nFunción de Pacto:\nVivero de la Reina\nPacto:\nNoctifeéricos\n\nFunción de Pacto:\nSenda de Ascensión\nPacto:\nKyrian\n\nFunción de Pacto:\nFábrica de Abominaciones\nPacto:\nNecroseñores"}
MultiLanguageSpellData['mx'][336040] = {name = "Hinchazón de cardiñón", additional_info = "Instante\n[q]Hinchado por haber comido un cardiñón, lo que reduce su velocidad de movimiento un 65% durante 5 s."}
MultiLanguageSpellData['mx'][336041] = {name = "Roc de carne cosido al hueso", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Solo los sastres de carne que han demostrado dominar las magias de Maldraxxus tienen el poder para construir un roc de muerte de este tamaño.\"\nProfesión:\nCostura abominable\nZona:\nMaldraxxus"}
MultiLanguageSpellData['mx'][336042] = {name = "Roc de muerte descomunal", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los rocs de muerte son monstruosidades cosidas a partir de vísceras, huesos y órganos descartados por no ser necesarios para construir soldados de la Casa de Ensamblajes.\"\nBotín:\nError violeta\nZona:\nMaldraxxus"}
MultiLanguageSpellData['mx'][336043] = {name = "Vértigo de menteñón", additional_info = "Instante\n[q]Mareado por comer un menteñón que reduce la probabilidad de acertar un 50% durante 4 s."}
MultiLanguageSpellData['mx'][336044] = {name = "Silviñosis", additional_info = "Instante\n[q]Te enfermaste por haber comido un silviñón y quedas aturdido durante 3 s."}
MultiLanguageSpellData['mx'][336045] = {name = "Roc de plaga depredador", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El hambre eterna de Gieger es legendaria en la Casa de Ensamblajes, y no hay bestia demasiado grande ni demasiado huesuda para su estómago enorme.\"\nBotín:\nGieger\nPacto:\nNecroseñores\nZona:\nMaldraxxus"}
