MultiLanguageSpellData['mx'][337043] = {name = "Neblina pululante", additional_info = "[q0][Covenant Ability]Instante\n[q]Una niebla densa te rodea durante 8 s, lo que aumenta un 10% tu Esquivar.\n\n Inflige ([20% of Attack Power]) p. de daño de las sombras cada 1 s a los enemigos en un radio de 10 m. Cada vez que inflige daño obtienes 3 p. de poder rúnico, hasta un máximo de 15 p. Al superar los 5 objetivos, inflige menos daño."}
MultiLanguageSpellData['mx'][337044] = {name = "Marca pecaminosa", additional_info = "[q0][Covenant Ability]Instante\n[q]Aplica a un enemigo la marca de los venthyr, lo que reduce su velocidad de ataque cuerpo a cuerpo un 30% y su velocidad de lanzamiento un 30%, e inflige ([338% of Attack Power]) p. de daño de las sombras durante 8 s.\n\n Activar Metamorfosis aplica Marca pecaminosa a todos los enemigos cercanos."}
MultiLanguageSpellData['mx'][337045] = {name = "Frenesí voraz", additional_info = "[q0][Covenant Ability]Instante\n[q]Durante 20 s, los hechizos de druida que lanzas aumentan tu daño y sanación un 2% y la celeridad un 1%. Este efecto se acumula.\n\n Si pasas 2 s inactivo, el Frenesí te abruma, consume un 1% de tu salud por acumulación, te aturde durante 1 s y luego termina."}
MultiLanguageSpellData['mx'][337046] = {name = "Tiro despellejador", additional_info = "[q0][Covenant Ability]Instante\n[q]Le disparas a un enemigo, lo que inflige ([50% of Attack Power]) p. de daño de las sombras y lo hace sangrar por ([112.5% of Attack Power]) p. de daño de las sombras durante 18 s. Cada vez que Tiro despellejador inflige daño, tienes un 15% de probabilidad de obtener la Marca del despellejador, que hace que tu próximo Disparo mortal no tenga costo, pueda usarse en cualquier objetivo sin importar su salud actual e inflija un 25% más de daño."}
MultiLanguageSpellData['mx'][337047] = {name = "Aliento necrótico", additional_info = "Alcance de 300 mHechizo de 3 seg 5 seg de reutilización\n[q]Inflige 40 p. de daño de las sombras a todos los enemigos que están frente al taumaturgo y reduce un 50% la sanación recibida durante 6 s."}
MultiLanguageSpellData['mx'][337048] = {name = "Espejos de tormento", additional_info = "[q0][Covenant Ability]Instante\n[q]Conjura 3 espejos para que atormenten al enemigo durante 25 s. Cada vez que el objetivo ataca, lanza un hechizo o usa una habilidad, se consume un espejo, inflige ([60% of Spell Power]) p. de daño de las sombras y reduce un 15% sus velocidades de movimiento y lanzamiento. Este efecto no se puede activar más de una vez cada 6 s.\n\n El último espejo, en cambio, inflige ([151% of Spell Power]) p. de daño de las sombras al enemigo, lo enraíza y lo silencia durante 4 s.\n\n Cada vez que se consume un espejo [ Arcano : obtienes Lanzamiento libre ] [ Fuego : el tiempo de reutilización de tu Explosión de fuego se reduce 6 s ] [ Escarcha : obtienes Congelación cerebral ]"}
MultiLanguageSpellData['mx'][337049] = {name = "Explosión escalofriante", additional_info = "Alcance de 200 m\nHechizo de 3 seg\n[q]Inflige 5 p. de daño de escarcha a los enemigos que están en un radio de 8 m y 1 p. de daño de escarcha cada 2 s, además de reducir un 50% la velocidad de movimiento durante 8 s."}
MultiLanguageSpellData['mx'][337050] = {name = "Santificación cinérea", additional_info = "[q0][Covenant Ability]Instante\n[q]Santifica el área objetivo durante 30 s. Los enemigos dentro del área reciben hasta [([55% of Spell Power]) * 30 / 2] p. de daño de las sombras, y los aliados reciben hasta [([36% of Spell Power]) * 30 / 2] p. de sanación, o una cantidad reducida si hay más de 5 objetivos.\n\n Dentro de la Santificación, puedes usar Martillo de cólera en cualquier objetivo y su daño aumenta un 100%."}
MultiLanguageSpellData['mx'][337051] = {name = "Juegos mentales", additional_info = "[q0][Covenant Ability]Instante\n[q]Atacas la mente del enemigo, le infliges [([300% of Spell Power]) * 100 / 100] p. de daño de las sombras e inviertes su percepción de la realidad brevemente.\n\n [ Sombra : Durante 5 s, los siguientes [(Poder con hechizos de las sombras * 450 / 100) * (1 + Versatilidad) * 100 / 100] p. de daño que inflija sanarán a su objetivo, y los siguientes [(Poder con hechizos de las sombras * 450 / 100) * (1 + Versatilidad) * 100 / 100] p. de sanación dañarán a su objetivo.\n\nLa sanación y el daño invertidos generan hasta 20 p. de demencia. /\n\nDisciplina, Sagrado\nDurante 5 s, los siguientes [(Poder con hechizos de las sombras * 450 / 100) * (1 + Versatilidad) * 100 / 100] p. de daño que inflija sanarán a su objetivo, y los siguientes [(Poder con hechizos de las sombras * 450 / 100) * (1 + Versatilidad) * 100 / 100] p. de sanación dañarán a su objetivo\n\nLa sanación y el daño invertidos restauran hasta un 4% de maná. ]"}
MultiLanguageSpellData['mx'][337052] = {name = "Flagelación", additional_info = "[q0][Covenant Ability]Instante\n[q]Azota al objetivo y le inflige ([50% of Attack Power]) p. de daño de las sombras e inflige un azote más por cada p. de combo gastado durante 12 s por ([10% of Attack Power]) p. de daño más. Infligir daño con Flagelación aumenta tu celeridad un 1%, persiste 12 s después de que su tormento termine."}
MultiLanguageSpellData['mx'][337053] = {name = "Explosión escalofriante", additional_info = "Alcance de 200 m\nInstante\n[q]Inflige 5 p. de daño de escarcha a los enemigos que están en un radio de 8 m y 1 p. de daño de escarcha cada 2 s, además de reducir un 50% la velocidad de movimiento durante 8 s."}
MultiLanguageSpellData['mx'][337054] = {name = "Cosecha en cadena", additional_info = "[q0][Covenant Ability]Instante\n[q]Despide una oleada de ánima hacia el objetivo que luego salta a otros objetivos cercanos. Inflige ([205% of Spell Power]) p. de daño de las sombras a un máximo de 5 enemigos, y restaura ([315% of Spell Power]) p. de salud a un máximo de 5 aliados.\n\n Por cada objetivo que recibe un golpe crítico, el tiempo de reutilización de Cosecha en cadena se reduce 5 s. [ Maestría: Sobrecarga elemental : Genera 3 p. de vorágine por cada objetivo golpeado o sanado ]"}
MultiLanguageSpellData['mx'][337055] = {name = "Catástrofe inminente", additional_info = "[q0][Covenant Ability]Instante\n[q]Invoca una nube de ánima caótica que viaja hasta el enemigo objetivo e inflige ([25.3% of Spell Power]) p. de daño de las sombras a los enemigos que están en su camino. Cuando el ánima llega a su objetivo, explota, aplica Maldición de debilidad o Maldición de las lenguas e inflige ([138% of Spell Power]) p. de daño de las sombras durante 12 s a todos los enemigos cercanos."}
MultiLanguageSpellData['mx'][337056] = {name = "Condenar", additional_info = "[q0][Covenant Ability]Instante\n[q]Aprende Condenar, que reemplaza Ejecutar. Condenar inflige daño de las sombras y se puede usar contra enemigos que tienen más del 80% de salud o menos del 20%, además de debilitar al objetivo para que te inflija menos daño."}
MultiLanguageSpellData['mx'][337057] = {name = "[q5]Reliquia de sinergia demoníaca", additional_info = "Poder de talla de runas\nAproximadamente 3 activaciones por minuto\n[q2]Cuando tu demonio o tú infligen daño, hay una probabilidad de otorgarle al otro un [ Demonología : 15% /\n\nAflicción, Destrucción\n10% ] más de daño durante 15 s.\n[q]Tallado rúnico en: Cabeza, Hombro, Espalda\n[q]Requiere: Brujo"}
